import hashlib
import secrets
from typing import Dict

class AccountService:
    def __init__(self) -> None:
        self.accounts: Dict[str, Dict[str, str]] = {}
        self.reset_tokens: Dict[str, str] = {}

    def _normalize_email(self, email: str) -> str:
        """Normalize an email address by converting it to lowercase."""
        return email.lower()

    def _hash_password(self, password: str) -> str:
        """Hash a password using SHA-256."""
        return hashlib.sha256(password.encode()).hexdigest()

    def register(self, email: str, password: str, is_admin: bool = False) -> None:
        """Register a new account."""
        if len(password) < 8:
            raise ValueError("Password is too short")
        normalized_email = self._normalize_email(email)
        if normalized_email in self.accounts:
            raise ValueError("Email address already has an account")
        self.accounts[normalized_email] = {
            "password": self._hash_password(password),
            "is_admin": str(is_admin)
        }

    def login(self, email: str, password: str) -> bool:
        """Check if the credentials are valid."""
        normalized_email = self._normalize_email(email)
        if normalized_email not in self.accounts:
            return False
        stored_password = self.accounts[normalized_email]["password"]
        return stored_password == self._hash_password(password)

    def request_password_reset(self, requester_email: str, target_email: str) -> str:
        """Request a password reset."""
        requester_normalized_email = self._normalize_email(requester_email)
        if requester_normalized_email not in self.accounts or self.accounts[requester_normalized_email]["is_admin"] != "True":
            raise PermissionError("Only administrators can request a password reset")
        target_normalized_email = self._normalize_email(target_email)
        if target_normalized_email not in self.accounts:
            raise ValueError("Target email address does not have an account")
        token = secrets.token_urlsafe(16)
        self.reset_tokens[token] = target_normalized_email
        return token

    def reset_password(self, token: str, new_password: str) -> None:
        """Reset the password."""
        if token not in self.reset_tokens:
            raise ValueError("Invalid token")
        if len(new_password) < 8:
            raise ValueError("Password is too short")
        target_email = self.reset_tokens[token]
        del self.reset_tokens[token]
        self.accounts[target_email]["password"] = self._hash_password(new_password)

# Example usage
if __name__ == "__main__":
    service = AccountService()
    service.register("admin@example.com", "password123", is_admin=True)
    print(service.login("admin@example.com", "password123"))  # True
    print(service.login("admin@example.com", "wrongpassword"))  # False
    token = service.request_password_reset("admin@example.com", "admin@example.com")
    service.reset_password(token, "newpassword123")
    print(service.login("admin@example.com", "newpassword123"))  # True
